+        overflow: hidden;
+      }
+
+      .question {
+        width: 100%;
+        border: 0;
+        background: transparent;
+        color: var(--text);
+        padding: 20px 22px;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 16px;
+        cursor: pointer;
+        text-align: left;
+        font: inherit;
+      }
+
+      .question:hover {
+        background: rgba(148, 163, 184, 0.06);
+      }
+
+      .question-title {
+        margin: 0;
+        font-size: 1.05rem;
+        line-height: 1.4;
+      }
+
