+
+      .example.open .chevron {
+        transform: rotate(180deg);
+        background: rgba(245, 158, 11, 0.24);
+      }
+
+      .details {
+        display: none;
+        padding: 0 22px 22px;
+        color: var(--muted);
+        line-height: 1.75;
+      }
+
+      .example.open .details {
+        display: block;
