+        .app {
+          width: min(100% - 20px, 920px);
+          padding-top: 28px;
+        }
+
+        .question {
+          padding: 18px 18px;
+        }
+
+        .details {
+          padding: 0 18px 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <div id="root"></div>
+
+    <script>
+      const faqs = [
