+            </button>
+            <div class="details" role="region">
+              <p>${answer}</p>
+            </div>
+          </div>
+        `;
+      }
+
+      function App() {
+        return `
+          <main class="app">
+            <section class="hero">
+              <div class="eyebrow">Cat FAQ</div>
+              <h1>Everything you wanted to ask about cats.</h1>
+              <p class="lede">
